\[
P(\text{Honest}\mid\text{data})=\frac{P(H)\,L_H}{P(H)L_H+P(D)L_D}
= \frac{0.4\,(0.8)^4(0.2)^2}{0.4\,(0.8)^4(0.2)^2+0.6\,(0.3)^4(0.7)^2}
= \frac{32{,}768}{44{,}675}\approx 0.733475.
\]

